export const CREW_APP_FILES: readonly CrewTextFile[] = [
  { path: "README.md", content: "# CHIMERA // LAB — Kiro Crew app\n\nA [Kiro Crew](https://github.com/kirodotdev/KiroCrew) app that audits slow SQL, N+1 query loops and missing composite indexes. It proposes fixes as SQL and code diffs and never applies them on its own.\n\n| Resource | File |\n| --- | --- |\n| Manifest | `app.json` |\n| Agents | `agents/chimera-architect.json`, `agents/index-surgeon.json`, `agents/deadlock-hunter.json` (`model: auto`, `tools: [\"@kirocrew-core\"]`) |\n| Skill | `skills/bio-query-optimizer/SKILL.md` |\n| Crons (all ship paused) | `chimera-bottleneck-audit` `0 */6 * * *` (architect), `chimera-nightly-index-review` `0 3 * * *` (index surgeon), `chimera-lock-watch` `*/30 * * * *` (deadlock hunter) |\n| Dashboard page | `ui/src/App.tsx`, built to `dist/index.mjs` |\n| Lifecycle hooks | `backend/hooks.py` (prerequisite checks only) |\n\n## Install\nRequires Kiro Crew running (`kirocrew gateway`), plus Node.js 22.12+ and git.\n\n```bash\nkirocrew app install /absolute/path/to/kiro-crew-app   # runs: cd ui && npm install && npm run build\n```\n\nBefore enabling, trust the app. Enabling from the App Store asks you to trust it, or use Settings → Security → Third-party apps. Then:\n\n```bash\nkirocrew app enable chimera-lab\n```\n\n\"Chimera Lab\" appears in the dashboard sidebar.\n\n## Configure the crons\nAll three crons are registered paused because they need a target repository and database first.\n\n1. In the environment that runs `kirocrew gateway`, set:\n   - `CHIMERA_PROJECT_DIR`: the repository to audit.\n   - `CHIMERA_DATABASE_URL` (optional): a **read-only** PostgreSQL URL. EXPLAIN checks need `psql`.\n2. Restart the gateway, then resume the crons you want from the dashboard's cron list. The index review and lock watch need `CHIMERA_DATABASE_URL`.\n\nThe lifecycle hooks report a degraded status while `CHIMERA_PROJECT_DIR` is missing or the UI bundle has not been built.\n\n## Run an audit by hand\nFrom the Chimera Lab page, press **Draft audit in chat**. Or ask in any chat:\n\n> Use the chimera-architect agent to audit ~/projects/shop-api for slow queries and N+1 loops.\n\n## Safety\n- The agents propose `CREATE INDEX CONCURRENTLY` / `DROP INDEX` statements and batched rewrites. They do not run DDL, migrations, file edits or `pg_cancel_backend` unless you approve that exact change.\n- It runs `EXPLAIN` without `ANALYZE` unless it is on a replica or inside `BEGIN; ... ROLLBACK;`.\n- `permissions.network` is `false`. The page only reads `/api/crons` and `/api/status` and listens for `notification` events.\n\n## Development\nThe dashboard page does not install or bundle `@kirocrew/app-sdk` or React; the Crew host provides both through its import map. `ui/src/kirocrew-app-sdk.d.ts` is a small local type subset. To get the full types, replace it with the dashboard's declarations:\n\n```bash\ncurl --fail -o ui/src/kirocrew-app-sdk.d.ts http://localhost:5476/vendor/kirocrew-app-sdk.d.ts\n```\n\nBuilt to the Kiro Crew App Kit docs: [manifest reference](https://kiro.dev/docs/crew/apps/manifest/) and [getting started](https://github.com/kirodotdev/KiroCrew/blob/main/docs/app-kit/getting-started.md).\n" },
  { path: "agents/chimera-architect.json", content: "{\n  \"name\": \"chimera-architect\",\n  \"model\": \"auto\",\n  \"description\": \"Database and query-path architect. Inspects schemas, git history and EXPLAIN plans, then proposes indexes and N+1 rewrites.\",\n  \"prompt\": \"You are CHIMERA, a database performance architect. Use the bio-query-optimizer skill for every audit.\\n\\nWork in this order:\\n1. Locate the schema: migrations, ORM models, or `\\\\d+ <table>` through psql when a read-only database URL is provided.\\n2. Read recent git history (`git log --since=<window> -p -- <source dirs>`) and list new or changed queries, including queries built by an ORM inside loops.\\n3. For each candidate query, run `EXPLAIN (FORMAT TEXT)` without ANALYZE. Only use `EXPLAIN (ANALYZE, BUFFERS)` on a read replica or inside `BEGIN; ... ROLLBACK;`, and never for statements that write.\\n4. Classify findings: sequential scans on tables above 10,000 rows, N+1 loops, missing composite indexes, sorts that an index could satisfy, and joins whose inner side lacks an index on the join key.\\n5. Propose fixes as SQL and code diffs: `CREATE INDEX CONCURRENTLY` statements with the column order from the skill, and batched rewrites using `= ANY($1)`.\\n\\nRules:\\n- Never run DDL, DML or migrations, and never edit files, unless the user explicitly approves that exact change.\\n- Never print credentials or full connection strings.\\n- Report estimated cost before and after each change and say whether the numbers come from EXPLAIN estimates or measured ANALYZE output.\\n- When a dashboard update is requested, emit @json-render RFC 6902 JSON Patch lines as described in the skill.\\n- Keep the report short: a findings table first, then one section per proposed change.\",\n  \"tools\": [\"@kirocrew-core\"]\n}\n" },
  { path: "agents/deadlock-hunter.json", content: "{\n  \"name\": \"deadlock-hunter\",\n  \"model\": \"auto\",\n  \"description\": \"Finds lock waits, blocking chains, long transactions and N+1 round-trip storms, and explains how to break them.\",\n  \"prompt\": \"You are the CHIMERA deadlock hunter. Use the bio-query-optimizer skill. You only read; you never cancel or terminate backends.\\n\\nWith the read-only database URL in $CHIMERA_DATABASE_URL:\\n1. Blocking chains: `SELECT pid, pg_blocking_pids(pid) AS blocked_by, state, wait_event_type, now() - xact_start AS xact_age, left(query, 200) AS query FROM pg_stat_activity WHERE cardinality(pg_blocking_pids(pid)) > 0;`.\\n2. Long or idle transactions: sessions with `state = 'idle in transaction'` or `now() - xact_start > interval '5 minutes'`.\\n3. Lock pressure: `SELECT locktype, mode, count(*) FROM pg_locks WHERE NOT granted GROUP BY 1, 2;`.\\n4. If the repository is in $CHIMERA_PROJECT_DIR, search recent commits for queries issued inside loops (N+1 storms) and for transactions that touch tables in different orders, a common deadlock cause.\\n5. If server logs are readable, count `deadlock detected` lines from the last 24 hours.\\n\\nReport the blocking tree, the oldest transactions, and for each problem a fix: consistent lock ordering, shorter transactions, `lock_timeout`, or batching N+1 loops with `= ANY($1)`. Suggest `pg_cancel_backend` only as a manual step for a human.\",\n  \"tools\": [\"@kirocrew-core\"]\n}\n" },
  { path: "agents/index-surgeon.json", content: "{\n  \"name\": \"index-surgeon\",\n  \"model\": \"auto\",\n  \"description\": \"Nightly index review. Finds missing composite indexes, unused indexes and duplicate prefixes, and proposes CREATE INDEX CONCURRENTLY or DROP INDEX statements.\",\n  \"prompt\": \"You are the CHIMERA index surgeon. Use the bio-query-optimizer skill. You only read; you never run DDL.\\n\\nWith the read-only database URL in $CHIMERA_DATABASE_URL:\\n1. Read the slowest statements: `SELECT query, calls, mean_exec_time, rows FROM pg_stat_statements ORDER BY total_exec_time DESC LIMIT 20;` (skip this step if the extension is missing and say so).\\n2. Run `EXPLAIN (FORMAT TEXT)` on each and list sequential scans on tables above 10,000 rows.\\n3. Read index usage: `SELECT schemaname, relname, indexrelname, idx_scan, pg_size_pretty(pg_relation_size(indexrelid)) FROM pg_stat_user_indexes ORDER BY idx_scan ASC LIMIT 30;`.\\n4. Flag indexes with idx_scan = 0 that are not primary keys or unique constraints, and indexes whose columns are a prefix of another index on the same table.\\n\\nReport three tables: proposed new indexes (with the equality, sort, range column order and estimated cost before and after), unused indexes, and redundant prefixes. Mark every DROP as needing a check of replicas and recent stats resets before anyone runs it.\",\n  \"tools\": [\"@kirocrew-core\"]\n}\n" },
  { path: "app.json", content: "{\n  \"name\": \"chimera-lab\",\n  \"version\": \"1.1.0\",\n  \"displayName\": \"CHIMERA // LAB\",\n  \"description\": \"Three database agents that audit slow SQL, review indexes nightly and hunt lock contention, proposing fixes without running them.\",\n  \"author\": \"GenUI Studio\",\n  \"license\": \"MIT\",\n  \"minKiroCrewVersion\": \"0.1.0\",\n  \"tags\": [\"database\", \"postgres\", \"performance\", \"sql\", \"code-review\"],\n  \"highlights\": [\n    \"Reads EXPLAIN plans and flags sequential scans on large tables\",\n    \"Detects N+1 query loops in application code and proposes batched rewrites\",\n    \"Designs composite indexes (equality, sort, range) with CREATE INDEX CONCURRENTLY\",\n    \"Nightly review of unused and redundant indexes\",\n    \"Finds blocking chains, long transactions and lock waits\",\n    \"Proposes changes only; never runs DDL or cancels backends\"\n  ],\n  \"agents\": [\"agents/chimera-architect.json\", \"agents/index-surgeon.json\", \"agents/deadlock-hunter.json\"],\n  \"skills\": [\"skills/bio-query-optimizer\"],\n  \"crons\": [\n    {\n      \"name\": \"chimera-bottleneck-audit\",\n      \"cron_expr\": \"0 */6 * * *\",\n      \"message\": \"Run a CHIMERA bottleneck audit with the bio-query-optimizer skill. Use the repository in $CHIMERA_PROJECT_DIR and, if set, the read-only database URL in $CHIMERA_DATABASE_URL. Review git commits from the last six hours for new queries and loops that issue queries, run EXPLAIN (no ANALYZE) on the slowest statements, and report sequential scans, N+1 patterns and missing composite indexes with proposed SQL. Do not run DDL or modify files.\",\n      \"agent\": \"chimera-architect\",\n      \"enabled\": false\n    },\n    {\n      \"name\": \"chimera-nightly-index-review\",\n      \"cron_expr\": \"0 3 * * *\",\n      \"message\": \"Run the nightly CHIMERA index review against the read-only database in $CHIMERA_DATABASE_URL: propose missing composite indexes for the slowest statements and list unused or redundant indexes. Do not run DDL.\",\n      \"agent\": \"index-surgeon\",\n      \"enabled\": false\n    },\n    {\n      \"name\": \"chimera-lock-watch\",\n      \"cron_expr\": \"*/30 * * * *\",\n      \"message\": \"Check the read-only database in $CHIMERA_DATABASE_URL for blocking chains, long or idle-in-transaction sessions and ungranted locks. Report only when something is blocked or a transaction is older than five minutes. Do not cancel or terminate backends.\",\n      \"agent\": \"deadlock-hunter\",\n      \"enabled\": false\n    }\n  ],\n  \"ui\": {\n    \"entry\": \"dist/index.mjs\",\n    \"pages\": [\n      {\n        \"route\": \"/apps/chimera-lab\",\n        \"label\": \"Chimera Lab\",\n        \"icon\": \"Dna\"\n      }\n    ],\n    \"sidebar\": {\n      \"section\": \"Apps\",\n      \"order\": 20\n    }\n  },\n  \"backend\": {\n    \"hooks\": {\n      \"on_startup\": \"backend.hooks:on_startup\",\n      \"on_shutdown\": \"backend.hooks:on_shutdown\"\n    }\n  },\n  \"permissions\": {\n    \"api\": [\"/api/crons\", \"/api/status\"],\n    \"events\": [\"notification\"],\n    \"cron\": true,\n    \"storage\": false,\n    \"network\": false\n  },\n  \"dependencies\": {\n    \"managedBy\": \"gateway\",\n    \"commands\": [\"git\", \"node\", \"npm\"],\n    \"optionalCommands\": [\"psql\"]\n  },\n  \"setup\": {\n    \"onInstall\": \"cd ui && npm install && npm run build\",\n    \"onUpdate\": \"cd ui && npm install && npm run build\"\n  },\n  \"platform\": {\n    \"os\": [\"macos\", \"linux\"]\n  }\n}\n" },
  { path: "backend/__init__.py", content: "\"\"\"CHIMERA // LAB backend lifecycle hooks for Kiro Crew.\"\"\"\n" },
  { path: "backend/hooks.py", content: "\"\"\"Lifecycle hooks for the CHIMERA // LAB Kiro Crew app.\n\nDeclared in app.json as ``backend.hooks.on_startup`` and ``backend.hooks.on_shutdown``.\nThey run inside the Kiro Crew gateway process when the app is enabled or disabled.\n\nThe hooks only check prerequisites and report problems through ``ctx.health``. They start\nno background work, so ``on_shutdown`` has nothing to stop.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport os\nimport shutil\nfrom pathlib import Path\n\nAPP_ROOT = Path(__file__).resolve().parent.parent\nUI_BUNDLE = APP_ROOT / \"dist\" / \"index.mjs\"\n\n\ndef _mark_degraded(ctx, message: str) -> None:\n    health = getattr(ctx, \"health\", None)\n    if health is not None and hasattr(health, \"mark_degraded\"):\n        health.mark_degraded(message)\n\n\nasync def on_startup(ctx) -> None:\n    \"\"\"Report missing prerequisites without blocking the app.\"\"\"\n    if not UI_BUNDLE.is_file():\n        _mark_degraded(ctx, \"Dashboard bundle dist/index.mjs is missing. Run: cd ui && npm install && npm run build\")\n\n    if not os.environ.get(\"CHIMERA_PROJECT_DIR\"):\n        _mark_degraded(\n            ctx,\n            \"CHIMERA_PROJECT_DIR is not set. Set it in the gateway environment before resuming the \"\n            \"chimera-bottleneck-audit cron.\",\n        )\n\n    if os.environ.get(\"CHIMERA_DATABASE_URL\") and shutil.which(\"psql\") is None:\n        _mark_degraded(ctx, \"CHIMERA_DATABASE_URL is set but psql is not installed, so EXPLAIN checks are skipped.\")\n\n\nasync def on_shutdown(ctx) -> None:\n    \"\"\"Nothing to stop: on_startup starts no background work.\"\"\"\n    return None\n" },
  { path: "skills/bio-query-optimizer/SKILL.md", content: "---\nname: bio-query-optimizer\ndescription: Find slow SQL, N+1 query loops and missing composite indexes in a PostgreSQL-backed codebase, propose safe fixes, and report them as tables or @json-render patches.\nalways: false\ntriggers: slow query, n+1, explain plan, missing index, composite index, query optimization, sequential scan, chimera audit\n---\n\n# Bio-Query Optimizer\n\nThink of request traffic as a slime mould looking for food. Every query path is a tube. Cheap, indexed paths get reinforced; expensive paths starve. Your job is to find the starving tubes and show how to feed them.\n\n## 1. Gather evidence (read-only)\n1. Schema: read migrations or ORM models. With a read-only database URL, use `psql \"$CHIMERA_DATABASE_URL\" -c '\\d+ <table>'` and `SELECT relname, n_live_tup FROM pg_stat_user_tables ORDER BY n_live_tup DESC LIMIT 20;`.\n2. Slow statements: if `pg_stat_statements` is enabled, read `SELECT query, calls, mean_exec_time, rows FROM pg_stat_statements ORDER BY total_exec_time DESC LIMIT 20;`.\n3. Recent changes: `git log --since=\"6 hours ago\" --stat` and `git log -p` on data-access files.\n4. Plans: `EXPLAIN (FORMAT TEXT) <query>` with representative parameter values.\n   - `EXPLAIN ANALYZE` executes the statement. Only run it on a replica, or wrap it in `BEGIN; ... ROLLBACK;`.\n   - Never run `EXPLAIN ANALYZE` on statements that write.\n\n## 2. Read an EXPLAIN plan\n- `Seq Scan on orders (cost=0.00..18334.00 rows=1 width=97)` reads every page of the table. It is fine on small tables and a problem above about 10,000 rows when only a few rows match.\n- `cost=a..b` means a is the startup cost and b is the total cost, in planner units (`seq_page_cost = 1`). Rows are estimates.\n- `Index Scan using idx_orders_user_id on orders` uses a B-tree descent and then fetches heap pages.\n- `Bitmap Heap Scan` + `Bitmap Index Scan` gathers many matches, or ORs several indexes.\n- `Nested Loop` with an inner `Index Scan` is cheap per outer row. A `Nested Loop` with an inner `Seq Scan` is a red flag.\n- `Hash Join` builds a hash of the inner input and is good for large unsorted joins.\n- `Sort` above a scan, when an `ORDER BY ... LIMIT` exists, means an index on the sort column could stop the sort early.\n- With `ANALYZE, BUFFERS`: compare `rows=` estimated against actual. A 10× miss means stale statistics, so run `ANALYZE <table>`. `shared read` counts pages read from disk.\n\n## 3. Detect N+1 loops\nAn N+1 loop is one query for a list, then one query per item:\n```ts\nconst posts = await db.query(\"SELECT id, author_id FROM posts WHERE feed_id = $1\", [feedId]);\nfor (const post of posts) {\n  post.author = await db.query(\"SELECT * FROM users WHERE id = $1\", [post.author_id]); // N queries\n}\n```\nSignals:\n- An `await` query, or an ORM lazy load (`post.author`, `.related()`), inside `for` / `map` / `forEach`.\n- `pg_stat_statements` shows a statement with a huge `calls` count and tiny `rows` per call.\n- Logs show the same statement with different id parameters in a burst.\n\nBatched rewrite: one round trip, then group in memory.\n```sql\nSELECT * FROM users WHERE id = ANY($1);   -- $1 = array of author ids\n```\nOr join directly:\n```sql\nSELECT p.id, u.name FROM posts p JOIN users u ON u.id = p.author_id WHERE p.feed_id = $1;\n```\nORM equivalents: Prisma `include`, Django `select_related` / `prefetch_related`, Rails `includes`, SQLAlchemy `selectinload`.\n\n## 4. Design composite indexes\nFor one query, order the B-tree columns like this:\n1. **Equality** columns (`col = $1`, `col IN (...)`). Put the most selective first when several queries share a prefix.\n2. **Sort** column, when the query has `ORDER BY col [DESC] LIMIT n`. The index then returns rows in order and the scan stops after n rows.\n3. **Range** column (`>`, `<`, `BETWEEN`). Anything after a range column cannot be used for ordering.\n\nExample: `WHERE tenant_id = $1 AND status = 'open' ORDER BY created_at DESC LIMIT 50`\n```sql\nCREATE INDEX CONCURRENTLY idx_tickets_tenant_status_created\n  ON tickets (tenant_id, status, created_at DESC);\n```\nRules:\n- Always use `CREATE INDEX CONCURRENTLY` on live tables. It cannot run inside a transaction block.\n- An index on `(a, b)` also serves queries on `a` alone. Do not add a separate index on `a`.\n- Use partial indexes for hot subsets: `... WHERE status = 'open'`.\n- Every index slows writes and uses disk. Prefer one composite index over several single-column ones.\n- For pgvector, `ORDER BY embedding <=> $1 LIMIT k` needs an HNSW or IVFFlat index with the matching operator class (`vector_cosine_ops` for `<=>`, `vector_l2_ops` for `<->`, `vector_ip_ops` for `<#>`).\n\n## 5. Report findings\nLead with a table:\n\n| Severity | Finding | Location | Est. cost before → after | Proposed fix |\n| --- | --- | --- | --- | --- |\n| High | Seq Scan on `orders` (2.1M rows) | `src/checkout.ts:88` | 41,250 → 8.6 | `CREATE INDEX CONCURRENTLY idx_orders_user_status ON orders (user_id, status);` |\n\nSay whether costs are EXPLAIN estimates or measured ANALYZE timings. Never claim a measured speed-up you did not measure.\n\n## 6. Emit @json-render patches (on request)\nWhen asked to update a GenUI dashboard, output RFC 6902 JSON Patch lines, one JSON object per line (JSONL). Only use element types that exist in the target catalog, and keep paths under `/elements/<key>/...` or `/state/...`:\n```jsonl\n{\"op\":\"add\",\"path\":\"/elements/finding-orders-seq-scan\",\"value\":{\"type\":\"<CatalogComponent>\",\"props\":{\"title\":\"Seq Scan on orders\",\"severity\":\"high\",\"costBefore\":41250,\"costAfter\":8.6},\"children\":[]}}\n{\"op\":\"add\",\"path\":\"/elements/findings-list/children/-\",\"value\":\"finding-orders-seq-scan\"}\n```\nNever emit raw HTML, script tags or `javascript:` URLs in props.\n\n## 7. Safety\n- Propose. Do not apply. DDL, migrations and code edits need the user's explicit approval for the exact change.\n- Use read-only credentials. Never echo connection strings or passwords.\n- Large index builds on big tables take time and I/O. Mention table size and suggest an off-peak window.\n" },
  { path: "ui/package.json", content: "{\n  \"name\": \"chimera-lab-ui\",\n  \"private\": true,\n  \"version\": \"1.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"build\": \"vite build\"\n  },\n  \"devDependencies\": {\n    \"@vitejs/plugin-react\": \"^4.3.4\",\n    \"vite\": \"^6.1.0\"\n  }\n}\n" },
  { path: "ui/src/App.tsx", content: "// Classic JSX runtime: the bundle then needs only the \"react\" specifier, which the Crew host\n// provides through its import map alongside @kirocrew/app-sdk.\nimport React, { useEffect, useState } from \"react\";\nimport { useAppApi, useAppEvents, useChatLauncher } from \"@kirocrew/app-sdk\";\nimport { Card, CardTitle, PageHeader, StatCard } from \"@kirocrew/app-sdk/ui\";\n\nconst AUDIT_CRON = \"chimera-bottleneck-audit\";\nconst MAX_EVENTS = 8;\n\ninterface CronSummary {\n  readonly found: boolean;\n  readonly enabled: boolean | null;\n  readonly schedule: string;\n}\n\n/** The /api/crons response shape is not documented, so read only the fields this page needs. */\nfunction findAuditCron(payload: unknown): CronSummary {\n  const list: unknown[] = Array.isArray(payload)\n    ? payload\n    : payload && typeof payload === \"object\"\n      ? (Object.values(payload as Record<string, unknown>).find(Array.isArray) as unknown[] | undefined) ?? []\n      : [];\n  for (const item of list) {\n    if (!item || typeof item !== \"object\") continue;\n    const job = item as Record<string, unknown>;\n    const name = typeof job.name === \"string\" ? job.name : \"\";\n    if (!name.endsWith(AUDIT_CRON)) continue;\n    const enabled = typeof job.enabled === \"boolean\" ? job.enabled : null;\n    const schedule = typeof job.cron_expr === \"string\" ? job.cron_expr : \"0 */6 * * *\";\n    return { found: true, enabled, schedule };\n  }\n  return { found: false, enabled: null, schedule: \"0 */6 * * *\" };\n}\n\nfunction describeEvent(event: unknown): string {\n  if (event && typeof event === \"object\") {\n    const e = event as Record<string, unknown>;\n    for (const key of [\"title\", \"message\", \"text\", \"body\"]) {\n      if (typeof e[key] === \"string\" && e[key]) return String(e[key]).slice(0, 160);\n    }\n  }\n  return \"Notification received\";\n}\n\nexport default function ChimeraLabPage() {\n  const api = useAppApi();\n  const { openChat } = useChatLauncher();\n  const [cron, setCron] = useState<CronSummary | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [events, setEvents] = useState<readonly string[]>([]);\n\n  useEffect(() => {\n    let alive = true;\n    api\n      .get<unknown>(\"/api/crons\")\n      .then((payload) => {\n        if (alive) setCron(findAuditCron(payload));\n      })\n      .catch((err: unknown) => {\n        if (alive) setError(err instanceof Error ? err.message : \"Could not read cron jobs\");\n      });\n    return () => {\n      alive = false;\n    };\n  }, [api]);\n\n  useAppEvents(\"notification\", (event) => {\n    setEvents((prev) => [describeEvent(event), ...prev].slice(0, MAX_EVENTS));\n  });\n\n  const status = cron === null ? \"Loading\" : !cron.found ? \"Not registered\" : cron.enabled === false ? \"Paused\" : \"Active\";\n\n  const draftAudit = () =>\n    openChat({\n      agent: \"chimera-architect\",\n      autoSend: false,\n      message:\n        \"Run a CHIMERA bottleneck audit on this project with the bio-query-optimizer skill. Report sequential scans, N+1 loops and missing composite indexes with proposed SQL. Do not apply changes.\",\n    });\n\n  return (\n    <>\n      <PageHeader title=\"CHIMERA // LAB\" subtitle=\"Slow query and N+1 audits, proposed as indexes and batched rewrites\" />\n      <div className=\"px-6 pb-8 overflow-y-auto flex-1 min-h-0\">\n        <div className=\"grid gap-3.5 grid-cols-[repeat(auto-fit,minmax(160px,1fr))] mb-6\">\n          <StatCard label=\"Audit cron\" value={status} accent={status === \"Active\"} />\n          <StatCard label=\"Schedule\" value={cron?.schedule ?? \"0 */6 * * *\"} />\n          <StatCard label=\"Agent\" value=\"chimera-architect\" />\n        </div>\n\n        <Card>\n          <CardTitle>Run an audit now</CardTitle>\n          <p className=\"text-sm text-muted mb-3\">\n            Opens a draft chat with the chimera-architect agent. Nothing is sent until you press send.\n          </p>\n          <button type=\"button\" onClick={draftAudit} className=\"rounded-md border px-3 py-1.5 text-sm\">\n            Draft audit in chat\n          </button>\n        </Card>\n\n        {status === \"Paused\" && (\n          <Card>\n            <CardTitle>Finish setup</CardTitle>\n            <p className=\"text-sm text-muted\">\n              Set CHIMERA_PROJECT_DIR (and optionally a read-only CHIMERA_DATABASE_URL) in the gateway environment, then\n              resume the {AUDIT_CRON} cron.\n            </p>\n          </Card>\n        )}\n\n        {error && (\n          <Card>\n            <CardTitle>Cron status unavailable</CardTitle>\n            <p className=\"text-sm text-muted\">{error}</p>\n          </Card>\n        )}\n\n        <Card>\n          <CardTitle>Recent notifications</CardTitle>\n          {events.length === 0 ? (\n            <p className=\"text-sm text-muted\">No notifications since this page opened.</p>\n          ) : (\n            <ul className=\"text-sm space-y-1\">\n              {events.map((text, i) => (\n                <li key={`${i}-${text}`}>{text}</li>\n              ))}\n            </ul>\n          )}\n        </Card>\n      </div>\n    </>\n  );\n}\n\n// Keep the default React import referenced for the classic JSX runtime used by the Vite build.\nvoid React;\n" },
  { path: "ui/src/kirocrew-app-sdk.d.ts", content: "/**\n * Minimal local type subset for the Kiro Crew App SDK, covering only what App.tsx uses.\n *\n * The Crew dashboard serves the full declarations at /vendor/kirocrew-app-sdk.d.ts. To use\n * them, replace this file with:\n *   curl --fail -o ui/src/kirocrew-app-sdk.d.ts http://localhost:5476/vendor/kirocrew-app-sdk.d.ts\n * The SDK itself is never installed or bundled: the host provides it through its import map.\n */\n\ndeclare module \"@kirocrew/app-sdk\" {\n  export interface AppApi {\n    get<T = unknown>(path: string, init?: RequestInit): Promise<T>;\n  }\n  export function useAppApi(): AppApi;\n  export function useAppEvents(event: string, callback: (event: unknown) => void): void;\n  export interface OpenChatOptions {\n    readonly message: string;\n    readonly autoSend?: boolean;\n    readonly agent?: string;\n  }\n  export function useChatLauncher(): { openChat(options: OpenChatOptions): unknown };\n}\n\ndeclare module \"@kirocrew/app-sdk/ui\" {\n  import type { ReactNode } from \"react\";\n  export function PageHeader(props: { title: string; subtitle?: string }): ReactNode;\n  export function Card(props: { children?: ReactNode }): ReactNode;\n  export function CardTitle(props: { children?: ReactNode }): ReactNode;\n  export function StatCard(props: { label: string; value: ReactNode; accent?: boolean }): ReactNode;\n}\n" },
  { path: "ui/tsconfig.json", content: "{\n  \"compilerOptions\": {\n    \"target\": \"ES2022\",\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"Bundler\",\n    \"jsx\": \"react\",\n    \"strict\": true,\n    \"skipLibCheck\": true,\n    \"noEmit\": true\n  },\n  \"include\": [\"src\"]\n}\n" },
  { path: "ui/vite.config.mjs", content: "import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\n// Builds the dashboard page to ../dist/index.mjs (app.json -> ui.entry).\n// React and the Kiro Crew SDK come from the host import map, so they stay external.\nexport default defineConfig({\n  plugins: [react({ jsxRuntime: \"classic\" })],\n  build: {\n    outDir: \"../dist\",\n    emptyOutDir: true,\n    lib: {\n      entry: \"src/App.tsx\",\n      formats: [\"es\"],\n      fileName: () => \"index.mjs\",\n    },\n    rollupOptions: {\n      external: [\"react\", \"react-dom\", \"@kirocrew/app-sdk\", \"@kirocrew/app-sdk/ui\", \"lucide-react\", \"@tanstack/react-query\"],\n    },\n  },\n});\n" },
];
